START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20261001200650_AddFgsBillingCategoryAccounting') THEN
    CREATE TABLE setup."FgsBillingCategoryAccounting" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "BillingCategoryId" bigint NOT NULL,
        "RevenueAccountId" bigint,
        "CogsAccountId" bigint,
        "InventoryOffsetAccountId" bigint,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsBillingCategoryAccounting" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsBillingCategoryAccounting_TenantId_CompanyId_BillingCategoryId" UNIQUE ("TenantId", "CompanyId", "BillingCategoryId"),
        CONSTRAINT "FK_FgsBillingCategoryAccounting_FgsBillingCategory" FOREIGN KEY ("BillingCategoryId") REFERENCES setup."FgsBillingCategory" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_FgsBillingCategoryAccounting_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsBillingCategoryAccounting" IS 'Stores optional accounting configuration for tenant/company specific billing categories, including Revenue, COGS, and Inventory Offset GL account mappings. Accounting configuration is maintained separately from the billing category so it can remain optional.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."Id" IS 'Primary key identity of the billing category accounting record.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."TenantId" IS 'Tenant identifier owning this billing category accounting configuration.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."CompanyId" IS 'Company identifier within the tenant owning this billing category accounting configuration.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."BillingCategoryId" IS 'Identifier of the billing category to which the accounting configuration applies.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."RevenueAccountId" IS 'Optional GL account used to record revenue generated from the billing category.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."CogsAccountId" IS 'Optional GL account used to record cost of goods sold associated with the billing category.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."InventoryOffsetAccountId" IS 'Optional GL account used as the inventory offset account for inventory billing categories. This account applies only when the associated billing category is an Inventory billing category.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."CreatedOn" IS 'Date and time the billing category accounting configuration was created.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."CreatedBy" IS 'User identifier that created the billing category accounting configuration.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."UpdatedOn" IS 'Date and time the billing category accounting configuration was last updated.';
    COMMENT ON COLUMN setup."FgsBillingCategoryAccounting"."UpdatedBy" IS 'User identifier that last updated the billing category accounting configuration.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20261001200650_AddFgsBillingCategoryAccounting') THEN
    CREATE INDEX "IX_FgsBillingCategoryAccounting_BillingCategoryId" ON setup."FgsBillingCategoryAccounting" ("BillingCategoryId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20261001200650_AddFgsBillingCategoryAccounting') THEN
    CREATE INDEX "IX_FgsBillingCategoryAccounting_TenantId_CompanyId" ON setup."FgsBillingCategoryAccounting" ("TenantId", "CompanyId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20261001200650_AddFgsBillingCategoryAccounting') THEN
    INSERT INTO setup."__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261001200650_AddFgsBillingCategoryAccounting', '10.0.8');
    END IF;
END $EF$;
COMMIT;

